#define MAX_STEPS 200
#define MAX_DIST 200.
#define SURF_DIST .00001


float sphere(vec3 p, vec3 c, float r)
{
    return length(p - c) - r;
}

float plane(vec3 p, vec3 n, float d)
{
    return dot(p, n) - d;
}

