float metaball(vec3 p, vec3 c, float r)
{
 	return pow(r, 2.0) / (pow(p.x - c.x, 2.0) + pow(p.y - c.y, 2.0) + pow(p.z - c.z, 2.0));	   
}


float aabb(vec3 p, vec3 pos, vec3 size)
{
  vec3 q = abs(p - pos) - size;
  return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

float GetDist(vec3 p) 
{

    float d = MAX_DIST;


    //for (int sx = -50; sx < 50; sx++)
    //    for (int sy = -50; sy < 50; sy++)
    //    {
    //        vec3 pos = vec3(sx, 0, sy);
    //        
    //        d = min(d, sphere(p, pos, 1.));
    //    }

    d = min(d, aabb(p, vec3(2., 2., 10.), vec3(3.,1.,5.)));


    /*
    for (float i = 0.; i < 100.; i++)
    {
        float x = mod(i, 10.);
        float y = floor(i / 10.);
        vec3 pos = vec3(x, 0., y + 10.);

        pos.y += sin(x + iTime);

        d = min(d, sphere(p, pos, .5));

    }
    */


    d = min(d, plane(p, vec3(0., 1., 0.), 0.));

    return d;
}


float RayMarch(vec3 ro, vec3 rd)
{

    float da = 0.0;

    for (int i = 0; i < MAX_STEPS; i++)
    {
        vec3 ri = ro + rd * da;
        float d = GetDist(ri);
        da += d;


        if (da > MAX_DIST || d < SURF_DIST)
            break;
    }

    return da;

}

float sdSphere(vec3 p, float r )
{
  vec3 offset = vec3(0, 0, -2);
  return length(p - offset) - r;
}


vec3 GetNormal(vec3 point) 
{
    float EPSILON = SURF_DIST;

    float a = GetDist(vec3(point.x + EPSILON, point.y, point.z));
    float b = GetDist(vec3(point.x - EPSILON, point.y, point.z));
    float c = GetDist(vec3(point.x, point.y + EPSILON, point.z));
    float d = GetDist(vec3(point.x, point.y - EPSILON, point.z));
    float e = GetDist(vec3(point.x, point.y, point.z  + EPSILON));
    float f = GetDist(vec3(point.x, point.y, point.z - EPSILON));
    return normalize(vec3(a - b, c - d, e - f));
}

vec3 GetNormalold(vec3 p) {

/*
    vec2 e = vec2(SURF_DIST, 0);

    return normalize(
      e.xyy * GetDist(p + e.xyy) +
      e.yyx * GetDist(p + e.yyx) +
      e.yxy * GetDist(p + e.yxy) +
      e.xxx * GetDist(p + e.xxx));

    */
    float d = GetDist(p);
    vec2 e = vec2(SURF_DIST, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx));

    return normalize(n);
}

float GetLight(vec3 p) {
    vec3 lightPos = vec3(3, 15, 2);
    lightPos.xz += vec2(sin(iTime), cos(iTime)) * 2.;
    vec3 l = normalize(lightPos - p);
    vec3 n = GetNormal(p);

    //diffuse
    float dif = clamp(dot(n, l), 0., 1.);

    //shadows
    float d = RayMarch(p + n * SURF_DIST * 2., l);
    if (d < length(lightPos-p)) dif *= .1;

    return dif;
}
// Rotation matrix around the X axis.
mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

// Rotation matrix around the Y axis.
mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

// Rotation matrix around the Z axis.
mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}

vec2 r;
bool stored = false;

float PI = 3.1415926535;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{



    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    vec3 col = vec3(0);

    vec3 ro = vec3(0, 5, 0);
    vec3 rd = normalize(vec3(uv.x, uv.y, 1));


    float tilt = PI / 12.; //15 degree tilt
    float pan = 0.;

    rd *= rotateX(tilt) * rotateY(pan);

    float d = RayMarch(ro, rd);

    vec3 p = ro + rd * d;

    float dif = GetLight(p);
    col = vec3(dif);

    //col = pow(col, vec3(.4545));	// gamma correction


    fragColor = vec4(col,1.0);
}
